function [reports, diagnostics] = d16_eval_task_specific( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state)
%D16_EVAL_TASK_SPECIFIC Unified-only task evidence dispatch adapter.
%
% All non-D022 behavior delegates to the task-specific extractor. For D022, the
% energy-path report is replayed before it is reused by the closed-loop
% check. Final report order remains power branch, closed loop, energy path.

task = upper(string(spec.id));
scenario = string(scenarioId);
diagnostics = empty_diagnostics(task, scenario);
if task ~= "D022" || scenario ~= "nominal"
    reports = sat_eval_task_specific( ...
        modelName, spec, scenarioId, simOut, signals, baseReports, state);
    diagnostics.strategy = "task_specific_dispatch";
    diagnostics.reuse_reason = "NOT_APPLICABLE";
    return;
end

diagnostics.strategy = "d022_energy_report_reuse";
energyPath = evaluate_energy( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state);
[cachedState, reuseDiagnostics] = prepare_reuse_state( ...
    energyPath, modelName, spec, scenarioId, simOut, signals, ...
    baseReports, state, task, scenario);
diagnostics.energy_reuse_attempted = ...
    reuseDiagnostics.energy_reuse_attempted;
diagnostics.energy_reuse_used = reuseDiagnostics.energy_reuse_used;
diagnostics.cheap_replay_equal = reuseDiagnostics.cheap_replay_equal;
diagnostics.reuse_reason = reuseDiagnostics.reuse_reason;

closedLoop = evaluate_closed_loop( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, cachedState);

% Unit-test facts are intentionally allowed to contain arbitrary synthetic
% nested rows.  Never trust those rows as a cache: fall back to the
% standalone checker so fixture semantics remain consistent.
powerBranch = empty_reports();
reusePower = ~has_unit_test_facts(cachedState);
if reusePower
    [powerBranch, reusePower] = nested_power_report( ...
        closedLoop, task, scenario);
end
if ~reusePower
    powerBranch = evaluate_power_branch( ...
        modelName, spec, scenarioId, simOut, signals, baseReports, ...
        cachedState);
end
diagnostics.nested_power_report_reused = logical(reusePower);
reports = combine(combine(powerBranch, closedLoop), energyPath);
reports = validate_reports(reports, task, scenario);
end

function [cachedState, diagnostics] = prepare_reuse_state( ...
    energyPath, modelName, spec, scenarioId, simOut, signals, ...
    baseReports, state, task, scenario)
cachedState = state;
diagnostics = empty_diagnostics(task, scenario);
diagnostics.energy_reuse_attempted = true;
if has_any_test_facts(state)
    diagnostics.reuse_reason = "SYNTHETIC_FACT_STATE_BYPASS";
    return;
end
if ~isstruct(state) || ~isscalar(state) || ...
        ~isfield(state, "evidence") || ...
        ~isstruct(state.evidence) || ~isscalar(state.evidence)
    diagnostics.reuse_reason = "STATE_EVIDENCE_SCHEMA_INVALID";
    return;
end
replayState = state;
replayState.evidence.unit_test_energy_path_facts = ...
    energyPath.evidence;
replayedReport = evaluate_energy( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, ...
    replayState);
diagnostics.cheap_replay_equal = logical( ...
    isequaln(replayedReport, energyPath));
if ~diagnostics.cheap_replay_equal
    diagnostics.reuse_reason = "CHEAP_REPLAY_NOT_EQUIVALENT";
    return;
end
cachedState = replayState;
diagnostics.energy_reuse_used = true;
diagnostics.reuse_reason = "REPORT_REUSED";
end

function report = evaluate_energy( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state)
report = sat_check_D022_energy_path_ownership( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state);
end

function report = evaluate_closed_loop( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state)
report = sat_check_D022_closed_loop_ballast_ownership( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state);
end

function report = evaluate_power_branch( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state)
report = sat_check_D022_power_branch_ownership( ...
    modelName, spec, scenarioId, simOut, signals, baseReports, state);
end

function [report, reusable] = nested_power_report(closedLoop, task, scenario)
report = empty_reports();
reusable = false;
if ~isstruct(closedLoop) || ~isscalar(closedLoop) || ...
        ~isfield(closedLoop, "evidence") || ...
        ~isstruct(closedLoop.evidence) || ...
        ~isscalar(closedLoop.evidence) || ...
        ~isfield(closedLoop.evidence, "power_branch_report")
    return;
end
candidate = closedLoop.evidence.power_branch_report;
if ~isstruct(candidate) || ~isscalar(candidate)
    return;
end
required = {'task', 'id', 'kind', 'semantic_kind', 'scenario', ...
    'layer', 'evaluated', 'mandatory', 'ok', 'valid', 'score', ...
    'detail', 'evidence'};
if ~all(isfield(candidate, required))
    return;
end
try
    identityOk = string(candidate.task) == task && ...
        string(candidate.id) == "D022.power_branch_ownership" && ...
        string(candidate.kind) == "task_specific" && ...
        string(candidate.semantic_kind) == "structure" && ...
        string(candidate.scenario) == scenario && ...
        string(candidate.layer) == "qualification";
    logicalOk = scalar_logical(candidate.evaluated) && ...
        scalar_logical(candidate.mandatory) && ...
        scalar_logical(candidate.ok) && scalar_logical(candidate.valid);
    scoreOk = isnumeric(candidate.score) && isscalar(candidate.score) && ...
        isfinite(candidate.score) && candidate.score >= 0 && ...
        candidate.score <= 1;
    reusable = identityOk && logicalOk && scoreOk;
catch
    reusable = false;
end
if reusable
    report = candidate;
else
    report = empty_reports();
end
end

function tf = has_unit_test_facts(state)
tf = isstruct(state) && isscalar(state) && isfield(state, "evidence") && ...
    isstruct(state.evidence) && isscalar(state.evidence) && ...
    isfield(state.evidence, "unit_test_facts");
end

function tf = has_any_test_facts(state)
tf = false;
if ~isstruct(state) || ~isscalar(state) || ...
        ~isfield(state, "evidence") || ...
        ~isstruct(state.evidence) || ~isscalar(state.evidence)
    return;
end
tf = isfield(state.evidence, "unit_test_facts") || ...
    isfield(state.evidence, "unit_test_energy_path_facts");
end

function value = empty_diagnostics(task, scenario)
value = struct( ...
    "schema", "simuverity.d16-task-extractor-diagnostics.v1", ...
    "task", string(task), ...
    "scenario", string(scenario), ...
    "strategy", "", ...
    "energy_reuse_attempted", false, ...
    "energy_reuse_used", false, ...
    "cheap_replay_equal", false, ...
    "nested_power_report_reused", false, ...
    "reuse_reason", "", ...
    "affects_offline_score", false);
end

function tf = scalar_logical(value)
tf = islogical(value) && isscalar(value);
end

function out = combine(a, b)
if isempty(a)
    out = b;
elseif isempty(b)
    out = a;
else
    out = [a(:); b(:)]';
end
end

function rows = validate_reports(rows, task, scenario)
if isempty(rows)
    rows = empty_reports();
    return;
end
assert(isstruct(rows), "SimuVerity:D16UnifiedTaskDispatch:ReportSchema", ...
    "Task evaluator must return struct rows.");
required = {'task', 'id', 'kind', 'semantic_kind', 'scenario', ...
    'layer', 'evaluated', 'mandatory', 'ok', 'valid', 'score', ...
    'detail', 'evidence'};
for i = 1:numel(rows)
    row = rows(i);
    assert(all(isfield(row, required)), ...
        "SimuVerity:D16UnifiedTaskDispatch:ReportSchema", ...
        "Task evaluator row is missing required fields.");
    assert(string(row.task) == task && ...
        string(row.kind) == "task_specific", ...
        "SimuVerity:D16UnifiedTaskDispatch:ReportOwnership", ...
        "Task report ownership/kind mismatch.");
    assert(string(row.scenario) == scenario, ...
        "SimuVerity:D16UnifiedTaskDispatch:ReportScenario", ...
        "Scenario-local report scenario mismatch.");
    assert(any(string(row.layer) == ...
        ["qualification", "nominal", "robustness"]), ...
        "SimuVerity:D16UnifiedTaskDispatch:ReportLayer", ...
        "Invalid task report layer.");
    assert_scalar_logical(row, "evaluated");
    assert_scalar_logical(row, "mandatory");
    assert_scalar_logical(row, "ok");
    assert_scalar_logical(row, "valid");
    assert(isnumeric(row.score) && isscalar(row.score) && ...
        isfinite(row.score) && row.score >= 0 && row.score <= 1, ...
        "SimuVerity:D16UnifiedTaskDispatch:ReportScore", ...
        "Task report score must be a finite scalar in [0,1].");
end
ids = string({rows.id});
assert(numel(unique(ids)) == numel(ids), ...
    "SimuVerity:D16UnifiedTaskDispatch:DuplicateReport", ...
    "Task evaluator emitted duplicate report IDs.");
end

function assert_scalar_logical(row, field)
assert(islogical(row.(field)) && isscalar(row.(field)), ...
    "SimuVerity:D16UnifiedTaskDispatch:ReportLogical", ...
    "%s must be scalar logical.", field);
end

function rows = empty_reports()
rows = struct("task", {}, "id", {}, "kind", {}, ...
    "semantic_kind", {}, "scenario", {}, "layer", {}, ...
    "evaluated", {}, "mandatory", {}, "ok", {}, "valid", {}, ...
    "score", {}, "detail", {}, "evidence", {});
end
